commandLine.original:
# Get sizes of all core Python files
$files = @(
    "QCalc.py", "CondensedPhysics.py", "APIFetch.py", 
    "Phase5_Consolidated.py", "Phase6_Consolidated.py", "Phase7_Consolidated.py",
    "production_pipeline.py", "ExtractionLayer.py",
    "IPData.py", "OPData.py", "ValidationData.py",
    "CondensedPhysics_InputData.py", "CondensedPhysics_OutputData.py", "CondensedPhysics_Validation.py",
    "QCalc_API.py", "QCalc_test.py", "QCalc_validation.py"
)
foreach ($f in $files) {
    $item = Get-ChildItem -Path "C:\Users\tmsjd\source\repos\Daniel8Murphy0007\Star-Magic\$f" -ErrorAction SilentlyContinue
    if ($item) {
        $lines = (Get-Content $item.FullName -ErrorAction SilentlyContinue | Measure-Object -Line).Lines
        Write-Host "$f : $([math]::Round($item.Length/1KB,1)) KB, $lines lines, $($item.LastWriteTime)"
    } else {
        Write-Host "$f : NOT FOUND"
    }
}

